function svg(nome, cor) {
    var i = ICO[nome]; if (!i) return ""
    var abre = i.tipo === "F"
        ? '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="' + cor + '">'
        : '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="' + cor + '" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'
    return abre + i.svg + "</svg>"
}
// o Qt não lê "#AARRGGBB" dentro do SVG: a cor vai como #RRGGBB e a transparência como opacity no Image
function url(nome, cor) {
    var s = String(cor)
    if (s.length === 9) s = "#" + s.substr(3)
    return "data:image/svg+xml;utf8," + encodeURIComponent(svg(nome, s))
}
function marca() { return "data:image/svg+xml;utf8," + encodeURIComponent(MARCA) }
